      "code": "orders_table = dbutils.widgets.get(\"orders_table\")\ntarget_table = dbutils.widgets.get(\"target_table\")\nwatermark = dbutils.widgets.get(\"watermark\")\nkey_columns = dbutils.widgets.get(\"key_columns\")\n\nkey_cols = [k.strip() for k in key_columns.split(\",\")]",
