      "title": "Read incremental CDC feed from orders source",
      "code": "from pyspark.sql import functions as F\nfrom pyspark.sql.types import StringType, LongType\n\nwatermark_val = int(watermark) if watermark else 0\n\nsource_df = (\n    spark.read.table(orders_table)\n    .filter(F.col(\"updated_at\") > watermark_val)\n    .select(\n        F.col(\"order_id\").cast(StringType()).alias(\"order_id\"),\n        F.col(\"customer_id\").cast(StringType()).alias(\"customer_id\"),\n        F.col(\"order_status\").cast(StringType()).alias(\"order_status\"),\n        F.col(\"purchased_at\").cast(LongType()).alias(\"purchased_at\"),\n        F.col(\"delivered_at\").cast(LongType()).alias(\"delivered_at\"),\n        F.col(\"updated_at\").cast(LongType()).alias(\"updated_at\"),\n    )\n)",
      "cites": [
        "table:orders",
        "pattern:module.ingest-cdc",
        "standard:notebook.explicit-schemas-and-column-lists",
