      ]
    },
    {
      "title": "Validate quality rules before processing",
      "code": "valid_df = source_df.filter(\n    F.col(\"order_id\").isNotNull() & F.col(\"updated_at\").isNotNull()\n)",
      "cites": [
        "standard:notebook.quality-rules-run-before-writes"
      ]
    },
    {
      "title": "Collapse multiple CDC records per key keeping latest state",
      "code": "from pyspark.sql.window import Window\n\nwindow_spec = Window.partitionBy(*key_cols).orderBy(F.col(\"updated_at\").desc())\n\ndeduplicated_df = (\n    valid_df\n    .withColumn(\"row_num\", F.row_number().over(window_spec))\n    .filter(F.col(\"row_num\") == 1)\n    .drop(\"row_num\")\n)",
