    },
    {
      "title": "Merge deduplicated changes into silver target",
      "code": "from delta.tables import DeltaTable\n\ntarget_delta = DeltaTable.forName(spark, target_table)\n\njoin_condition = \" AND \".join([f\"target.{k} = updates.{k}\" for k in key_cols])\n\n(\n    target_delta.alias(\"target\")\n    .merge(\n        deduplicated_df.alias(\"updates\"),\n        join_condition\n    )\n    .whenMatchedUpdateAll()\n    .whenNotMatchedInsertAll()\n    .execute()\n)",
